const stageGuides={
overview:{icon:"route",title:"ObjectSensing pipeline",summary:"The RGB-D scene is reconstructed, described and compared with ShapeNet to retrieve a consistent set of CAD furniture models.",input:"RGB-D scene",process:"6 stages",output:"Placed objects",purpose:"Retrieve furniture CAD models from partial RGB-D observations and display the hypotheses in scene context.",data:"Color images, depth maps, camera poses and a preprocessed model database.",compute:"The pipeline combines volumetric fusion, keypoint detection, querying, registration, verification and global selection.",decision:"The result contains the observed scene surface, candidate poses and retained objects."},
fusion:{icon:"layers-3",title:"RGB-D fusion",summary:"Each depth map is projected into common coordinates and integrated into a TSDF volume.",input:"RGB-D + poses",process:"Fusion TSDF",output:"Surface 3D",purpose:"Build common, stable geometry from partial, noisy views.",data:"Depth, color, camera intrinsics and the camera-to-world transform of each frame.",compute:"Measurements update the truncated signed distance, observation weight and visibility of traversed voxels.",decision:"Extract an isosurface and a gravity-aligned scan for subsequent stages."},
keypoints:{icon:"crosshair",title:"Scene keypoints",summary:"Detect locally distinctive regions, then filter them to avoid concentrating on a single surface.",input:"Surface 3D",process:"Harris 3D + NMS",output:"Points distinctifs",purpose:"Reduce the scene to geometric anchors stable enough to propose correspondences.",data:"Reconstructed surface neighborhoods, normals, curvature and spatial position.",compute:"A 3D Harris score detects geometric variation; non-maximum suppression, deduplication and spatial balancing limit redundant points.",decision:"Retain the strongest surviving keypoints, spatially distributed and capped by max_scan_keypoints."},
query:{icon:"list-filter",title:"Top-k query",summary:"A compact index reduces the ShapeNet database to a shortlist of plausible candidates.",input:"Scene descriptor",process:"Indexed search",output:"Ranked Top-k",purpose:"Avoid expensive registration against every model in the database.",data:"Global descriptors and geometric statistics of the scene and preindexed models.",compute:"Descriptor distance produces a pool; ranking and diversity produce the final Top-k.",decision:"Candidates are ranked but not validated: a high rank only means they should undergo detailed matching."},
matching:{icon:"waypoints",title:"Constellation matching",summary:"Keypoint correspondences propose pose seeds, then orientation, translation and scale are adjusted.",input:"Keypoints + model",process:"Seeds + registration",output:"Pose hypotheses",purpose:"Find where and how each candidate can explain part of the scene.",data:"Scene and model keypoints, local descriptors and geometrically compatible constellations.",compute:"Constellations generate initial poses; the best are refined and scored for coverage and reverse consistency.",decision:"A model can produce zero, one or several hypotheses. Failures and rejection reasons are kept for diagnostics."},
verification:{icon:"badge-check",title:"Volumetric verification",summary:"Compare each hypothesis with the scene volume to reject incompatible placements.",input:"Placed hypotheses",process:"Tests SDF",output:"Valid hypotheses",purpose:"Determine whether a plausible placement is compatible with the observed 3D geometry.",data:"Observed surface, free space, unknown voxels, model SDF and coverage thresholds.",compute:"Verification measures forward/reverse coverage, structure, thickness, conflicts and visibility where available.",decision:"Hypotheses failing acceptance gates are rejected with a reason; the rest proceed to global selection."},
selection:{icon:"check-check",title:"Global selection",summary:"Resolve valid hypotheses jointly to avoid duplicates and inconsistent overlaps.",input:"Valid hypotheses",process:"Optimisation globale",output:"Retained objects",purpose:"Build a consistent scene explanation by considering interactions between hypotheses.",data:"Symmetric scores, categories, centers, bounding volumes, overlaps and category limits.",compute:"Global ranking favors geometric quality while penalizing duplicates, spatial conflicts and redundant explanations.",decision:"Final output contains retained models with placement, orientation, scale and selection diagnostics."}
};
