const notify=createNotifier({selector:"#toast",duration:3600});
function formatDuration(seconds){seconds=Math.max(0,Math.floor(seconds||0));return [Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(value=>String(value).padStart(2,"0")).join(":")}
function number(value,digits=2){const parsed=Number(value);return Number.isFinite(parsed)?parsed.toFixed(digits):"—"}
function pct(value){const parsed=Number(value);return Number.isFinite(parsed)?`${(parsed*100).toFixed(0)} %`:"—"}
function statusOf(candidate){return candidate?.status||candidate?.registration?.status||(candidate?.registration?"candidate":"pending")}
function accepted(candidate){return ["candidate","selected","kept","accepted_pose"].includes(statusOf(candidate))}
const rejectionLabels={insufficient_coverage:"insufficient coverage",rejected_coverage:"insufficient coverage",reverse_gate:"reverse consistency",structure:"incompatible structure",thickness:"incompatible thickness",collision:"collision",overlap:"superposition",duplicate:"duplicate",not_selected:"not retained",icp_or_scale:"ICP refinement or scale"};
const statusLabels={candidate:"plausible pose",selected:"retained",kept:"retained",accepted_pose:"pose accepted",pending:"waiting",rejected_coverage:"rejected for coverage",rejected:"rejected",no_registration:"no valid pose"};
function setInsightItems(host,items=[]){host.replaceChildren();items.filter(Boolean).forEach(item=>{const span=document.createElement("span");span.textContent=String(item.text??item);if(item.className)span.className=item.className;host.appendChild(span)})}
function eventInsight(phase,event=null,index=-1){const guide=stageGuides[phase]||stageGuides.overview,data=event?.data||{},context={...guide,kicker:phase==="overview"?"Overview":phaseLabels[phase],metrics:[],diagnostics:[]};
 if(event?.type==="fusion_frame"){const points=data.points?.length||0;context.kicker=`Fusion · event ${index+1}`;context.title=`Integrating frame ${data.frame_index||index+1}`;context.summary=`Depth from this view adds ${points} visible samples to the common reconstruction.`;context.metrics=[`Frame ${data.frame_index||index+1}`,`${points} points`,`Camera ${data.camera_position?.length===3?"localized":"without pose"}`];context.diagnostics=[`Frame index: ${data.frame_index||index+1}`,`Displayed samples: ${points}`,`Camera pose: ${data.camera_position?.length===3?data.camera_position.map(value=>number(value,2)).join(", "):"missing"}`]}
 else if(event?.type==="keypoints"){context.kicker=`Keypoints · event ${index+1}`;context.title=`${data.retained||0} keypoints retained`;context.summary=`${data.detected||0} points detected; quality and spatial filters retain ${data.retained||0}.`;context.metrics=[`${data.detected||0} detected`,`${data.retained||0} retained`,`${data.frame_count||0} frames`];context.diagnostics=[`Retention rate: ${data.detected?pct((data.retained||0)/data.detected):"—"}`,`Checkpoint : ${data.frame_count||0} frames`,`Positions available in trace: ${data.points?.length||0}`]}
 else if(event?.type==="query_reset"){context.kicker=`Top-k · event ${index+1}`;context.title="Building a new query";context.summary=`The current scene queries ${data.database_count||0} models, builds a pool of ${data.pool_count||0}, and retains ${data.top_k_count||0} candidates.`;context.metrics=[`${data.database_count||0} models`,`Pool ${data.pool_count||0}`,`Top-k ${data.top_k_count||0}`];context.diagnostics=[`Strategy: ${data.strategy||"unspecified"}`,`Checkpoint : ${data.frame_count||0} frames`,`Reduction: ${data.database_count?pct((data.top_k_count||0)/data.database_count):"—"} of the database` ]}
 else if(event?.type==="query_candidate"){context.kicker=`Top-k · rang ${data.rank||0}`;context.title=data.model||"Indexed candidate";context.summary=`This model ranks ${data.rank||0} out of ${data.top_k_count||0}; it is proposed for matching but not validated yet.`;context.metrics=[`Rang ${data.rank||0}/${data.top_k_count||0}`,`${data.database_count||0} in database`,`Checkpoint ${data.frame_count||0}`];context.diagnostics=[`Model identifier: ${data.model||"—"}`,`Preselection rank: ${data.rank||0}`,"Status: awaiting constellation matching"]}
 else if(event?.type==="matching_result"){const candidate=data.candidate||{},registration=candidate.registration||{},status=registration.status||statusOf(candidate),rejections=Object.entries(candidate.verification?.rejection_counts||{}).filter(([,value])=>Number(value)>0);context.kicker=`Matching · ${data.completed||0}/${data.total||0}`;context.title=candidate.model||"Tested candidate";context.summary=`${candidate.correspondences||0} correspondences and ${candidate.constellations||0} constellations yield: ${statusLabels[status]||status}.`;context.metrics=[`${candidate.correspondences||0} corr.`,`${candidate.constellations||0} const.`,`Couv. ${pct(registration.coverage)}`,accepted(candidate)?"Pose plausible":"Rejected"];context.diagnostics=[`Model: ${candidate.model||"—"}`,`Category: ${candidate.category||candidate.synset||"—"}`,`Forward coverage: ${pct(registration.coverage)}`,`Reverse coverage: ${pct(registration.cov_reverse)}`,`Scale: ${number(registration.scale,3)}`,`Orientation Y : ${number(registration.theta_deg,1)}°`,...rejections.map(([reason,count])=>({text:`${count} rejection(s) : ${rejectionLabels[reason]||reason}`,className:"rejected"}))]}
 else if(event?.type==="checkpoint_selection"){context.kicker=`Verification · event ${index+1}`;context.title=`${data.selected?.length||0} hypotheses retained at checkpoint`;context.summary=`Verification compares ${data.candidates||0} hypotheses with the reconstruction and passes compatible placements to selection.`;context.metrics=[`${data.candidates||0} hypotheses`,`${data.selected?.length||0} retenues`,`${data.frame_count||0} frames`];context.diagnostics=[`Hypotheses examined: ${data.candidates||0}`,`Hypotheses retained: ${data.selected?.length||0}`,`Diagnostics disponibles : ${data.diagnostics?.length||0}`]}
 else if(event?.type==="final_selection"){context.kicker="Final selection";context.title=`${data.selected?.length||0} objects explain the scene`;context.summary="Final selection balances quality, overlap, categories and redundancy across valid hypotheses.";context.metrics=[`${data.selected?.length||0} objects`,`${data.diagnostics?.length||0} decisions`,`${data.frame_count||0} frames`];context.diagnostics=(data.selected||[]).map(item=>({text:`Retained: ${item.model||item.category||"object"}`,className:"accepted"}));if(!context.diagnostics.length)context.diagnostics=[{text:"No object passed final selection",className:"rejected"}]}
 else if(event?.type==="phase_status"){context.summary=data.detail||guide.summary;context.metrics=[data.state==="completed"?"Completed":"Running"]}
 return context}
function updateStageInsight(phase="overview",event=null,index=-1){const context=eventInsight(phase,event,index),guide=stageGuides[phase]||stageGuides.overview;$("#phase-label").textContent=context.title;$("#phase-detail").textContent=context.summary;$("#stage-insight-icon").innerHTML=`<i data-lucide="${context.icon}"></i>`;$("#insight-kicker").textContent=context.kicker;$("#insight-title").textContent=context.title;$("#insight-summary").textContent=context.summary;$("#insight-input").textContent=context.input;$("#insight-process").textContent=context.process;$("#insight-output").textContent=context.output;setInsightItems($("#insight-metrics"),context.metrics.length?context.metrics:["Waiting"]);$("#detail-kicker").textContent=context.kicker;$("#detail-title").textContent=context.title;$("#detail-purpose").textContent=guide.purpose;$("#detail-data").textContent=guide.data;$("#detail-compute").textContent=guide.compute;$("#detail-decision").textContent=guide.decision;setInsightItems($("#event-diagnostics"),context.diagnostics.length?context.diagnostics:["No event metrics available for this view."]);iconRefresh()}
