function renderReplayChapters(){const host=$("#chapter-segments");if(!replay?.chapters?.length){host.innerHTML=phases.map(phase=>`<button class="chapter-segment" type="button" data-chapter="${phase}" data-label="${phaseLabels[phase]}" data-tooltip="${phaseLabels[phase]}" data-tooltip-detail="${stageGuides[phase].summary}" style="flex:1"></button>`).join("");drawEventTicks();drawEventRuler();return}host.innerHTML=replay.chapters.map(chapter=>`<button class="chapter-segment" type="button" data-chapter="${chapter.id}" data-label="${phaseLabels[chapter.id]} · ${chapter.count} stages" data-tooltip="${phaseLabels[chapter.id]} · ${chapter.count} events" data-tooltip-detail="${stageGuides[chapter.id].summary}" style="flex:${Math.max(1,chapter.count)}"></button>`).join("");$$('[data-chapter]',host).forEach(button=>button.addEventListener("click",()=>jumpReplayChapter(button.dataset.chapter)));drawEventTicks();drawEventRuler()}
