function activateReplay(payload,{collapse=true,loaded=false}={}){pauseReplay();if(collapse)app.classList.add("workflow-collapsed","inspector-collapsed");replay=payload;replayIndex=-1;rulerZoom=1;rulerSignature="";setSceneGround(payload.ground);app.classList.add("replay-mode");$("#timeline-mode").textContent=loaded?"HISTORIQUE":"REPLAY";$("#timeline-mode").className="timeline-mode replay";$("#run-name").textContent=payload.run.label||payload.run.id;$("#run-status").textContent=loaded?"Saved run loaded":"Saved replay";$("#run-context").textContent=loaded&&selectedRun?stageCaption(selectedRun):`${new Date(payload.run.modified*1000).toLocaleString()} · ground ${number(sceneGround,2)} m → Y=0`;$("#replay-slider").min=0;$("#replay-slider").max=Math.max(0,payload.events.length-1);setReplayControls(Boolean(payload.events.length));renderReplayChapters();if(payload.events.length){fitReplayCamera();renderReplay(0)}else if(payload.run.viz_url)loadPly(payload.run.viz_url);return payload}
