async function refreshDefaults(){try{const payload=await api("/api/defaults"),selectedScene=$("#scene-select").value;recentRuns=payload.recent_runs||[];sceneOptions=payload.scene_options||sceneOptions;renderSceneOptions(selectedScene);if(selectedRunId){const refreshed=recentRuns.find(run=>run.id===selectedRunId);if(refreshed)selectedRun=refreshed}renderHistory();if(selectedRun){markLoadedRun(selectedRun);renderSelectedRun()}}catch(error){notify(error.message,true)}}
