async function init(){try{const payload=await api("/api/defaults");defaults=payload.config;stepDefinitions=payload.steps;recentRuns=payload.recent_runs||[];sceneOptions=payload.scene_options||[];setForm(defaults);renderPlaylist();renderHistory();renderReplayChapters();updateStageInsight("overview");const state=await api("/api/state");lastEventId=state.last_event_id||0;applyState(state);if(innerWidth<820){app.classList.add("workflow-collapsed","inspector-collapsed")}bindUI();bindRunManagement();const savedRun=sessionStorage.getItem("objectsensing-selected-run");if(savedRun&&!state.running&&recentRuns.some(run=>run.id===savedRun&&run.resumable))await loadExistingRun(savedRun);iconRefresh();resize();poll()}catch(error){console.error("Run Console initialization failed",error);notify(error.message||"Run Console initialization failed",true)}}
$("#replay-slider").addEventListener("pointermove",event=>showSeekTooltip(event.clientX));
$("#replay-slider").addEventListener("pointerleave",()=>{$("#seek-tooltip").hidden=true});
