$("#event-ruler-scroll").addEventListener("pointerdown",event=>{if(replay){pauseReplay();renderReplay(rulerIndexAt(event.clientX))}});
$("#event-ruler-scroll").addEventListener("scroll",updateRulerWindow,{passive:true});
$("#event-ruler-cells").addEventListener("click",event=>{const cell=event.target.closest("[data-event-index]");if(!cell||!replay)return;pauseReplay();renderReplay(Number(cell.dataset.eventIndex))});
$("#ruler-zoom-out").addEventListener("click",()=>setRulerZoom(rulerZoom<=1?0:rulerZoom/2));
$("#ruler-zoom-fit").addEventListener("click",()=>setRulerZoom(0));
$("#ruler-zoom-in").addEventListener("click",()=>setRulerZoom(rulerZoom===0?1:Math.min(4,rulerZoom*2)));
document.addEventListener("click",event=>{if(event.target.closest("[data-replay-run],#start-run,#start-run-secondary,[data-manual-step]")){if(document.activeElement instanceof HTMLElement)document.activeElement.blur();app.classList.add("workflow-collapsed","inspector-collapsed");app.classList.remove("workflow-peeking","inspector-peeking");updatePanelToggles()}});
bindPanelResizers();
init();
